1	import { useState } from 'react';
2	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
3	import { getJson, postJson } from '../../api/http';
4	import { asFlag, asNumber, asString, useSearchParam } from '../../url/useSearchParam';
5	import type { Client } from '../clients/ClientsPage';
6	import type { ProjectTag } from './ProjectTagsPanel';
7	import { ProjectRowActions } from '../../slots/defs/projectRowActions';
8	import { ProjectsToolbar } from '../../slots/defs/projectsToolbar';
9	
10	// A project as the server returns it: it carries the client's NAME so the list shows the name, not
11	// the id. project.clientId is the id the form's select submits. `archived` projects are kept but
12	// hidden from the default list.
13	// A project's state: ACTIVE while worked on, ON_HOLD when paused, FINISHED when done. Stored on the
14	// row and pickable when creating a project (V21__project_status.sql).
15	export const PROJECT_STATUSES = ['ACTIVE', 'ON_HOLD', 'FINISHED'] as const;
16	export type ProjectStatus = (typeof PROJECT_STATUSES)[number];
17	
18	export type Project = {
19	  id: number;
20	  name: string;
21	  clientId: number;
22	  clientName: string;
23	  archived: boolean;
24	  status: ProjectStatus;
25	};
26	
27	// The projects page: the whole list of projects plus the form to add one and pick its client.
28	// Server data is read with useQuery (['projects'] for the list, ['clients'] — the SAME key the
29	// clients feature owns — for the select options) and changed with useMutation + invalidateQueries.
30	// The only useState here is the fields the user is currently filling in (rule 4).
31	export function ProjectsPage() {
32	  const queryClient = useQueryClient();
33	  const projects = useQuery({
34	    queryKey: ['projects'],
35	    queryFn: () => getJson<Project[]>('/api/projects'),
36	  });
37	  const clients = useQuery({
38	    queryKey: ['clients'],
39	    queryFn: () => getJson<Client[]>('/api/clients'),
40	  });
41	
42	  // Whether archived projects are revealed lives in the URL, owned by
43	  // features/projects/showArchived.slot.tsx. The page reads the same key: by default archived
44	  // projects drop off the list; the toggle brings them back — no server data copied into state.
45	  const [showArchived] = useSearchParam('showArchived', asFlag);
46	
47	  // Which tag the list is filtered to lives in the URL, owned by features/projects/tagFilter.slot.tsx.
48	  // The page reads the same key and narrows its rows to projects carrying that tag; the pairings come
49	  // from useQuery under ['projectTags'] — the SAME key the tags panel owns (rule 5) — so nothing is
50	  // passed between the control and the list. Undefined means no filter: every project shows.
51	  const [tagFilter] = useSearchParam('projectTag', asNumber);
52	
53	  // Which status the list is filtered to lives in the URL, owned by
54	  // features/projects/statusFilter.slot.tsx. The page reads the same key and narrows its rows to
55	  // projects at that status; empty means no filter, so every project shows.
56	  const [statusFilter] = useSearchParam('projectStatus', asString);
57	  const projectTags = useQuery({
58	    queryKey: ['projectTags'],
59	    queryFn: () => getJson<ProjectTag[]>('/api/project-tags'),
60	  });
61	
62	  const [name, setName] = useState('');
63	  const [clientId, setClientId] = useState('');
64	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
65	
66	  const create = useMutation({
67	    mutationFn: () =>
68	      postJson<Project>('/api/projects', { name, clientId: Number(clientId), status }),
69	    onSuccess: () => {
70	      setName('');
71	      setClientId('');
72	      setStatus('ACTIVE');
73	      void queryClient.invalidateQueries({ queryKey: ['projects'] });
74	    },
75	  });
76	
77	  const taggedIds = new Set(
78	    (projectTags.data ?? [])
79	      .filter((pt) => pt.tagId === tagFilter)
80	      .map((pt) => pt.projectId),
81	  );
82	  const rows = (projects.data ?? [])
83	    .filter((p) => showArchived || !p.archived)
84	    .filter((p) => tagFilter === undefined || taggedIds.has(p.id))
85	    .filter((p) => statusFilter === '' || p.status === statusFilter);
86	  const clientOptions = clients.data ?? [];
87	
88	  return (
89	    <section data-testid="projects">
90	      <form
91	        data-testid="project-form"
92	        onSubmit={(e) => {
93	          e.preventDefault();
94	          if (!name.trim() || !clientId) {
95	            return;
96	          }
97	          create.mutate();
98	        }}
99	      >
100	        <input
101	          data-testid="project-form-name"
102	          placeholder="Project name"
103	          value={name}
104	          onChange={(e) => setName(e.target.value)}
105	        />
106	        <select
107	          data-testid="project-form-client"
108	          value={clientId}
109	          onChange={(e) => setClientId(e.target.value)}
110	        >
111	          <option value="">Select a client</option>
112	          {clientOptions.map((c) => (
113	            <option key={c.id} value={c.id}>
114	              {c.name}
115	            </option>
116	          ))}
117	        </select>
118	        <select
119	          data-testid="project-form-status"
120	          value={status}
121	          onChange={(e) => setStatus(e.target.value as ProjectStatus)}
122	        >
123	          {PROJECT_STATUSES.map((s) => (
124	            <option key={s} value={s}>
125	              {s}
126	            </option>
127	          ))}
128	        </select>
129	        <button data-testid="project-form-submit" type="submit">
130	          Add project
131	        </button>
132	      </form>
133	
134	      <div data-testid="projects-toolbar">
135	        <ProjectsToolbar.Slot />
136	      </div>
137	
138	      {rows.length === 0 ? (
139	        <p data-testid="projects-empty">No projects yet.</p>
140	      ) : (
141	        <table data-testid="projects-table">
142	          <thead>
143	            <tr>
144	              <th>Name</th>
145	              <th>Client</th>
146	              <th>Status</th>
147	              <th />
148	            </tr>
